import React, { useContext } from 'react';
import { useCart, CartContext } from '../context/cartContext';
import { graphql, Link } from 'gatsby';
import Layout from '../components/layout';
import { UserProfile } from '../interfaces';
import data from '../data/data.json';
import { useTranslation } from 'gatsby-plugin-react-i18next';

const CheckoutPage = () => {
    const { t } = useTranslation();
  const cartContext = useContext(CartContext);
  if (!cartContext) {
    return <div>{t("cart.cartContextError")}</div>;
  }
  const userData: UserProfile = data;

  const { cart } = cartContext;

  // Calculate the subtotal
  const subtotal = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const provincialTaxValue = 0.09975;
  const federalTaxValue = 0.05;
  
  // Calculate the provincial and federal taxes
  const provincialTaxRate = provincialTaxValue; // 9.975% provincial tax
  const federalTaxRate = federalTaxValue; // 5% federal tax

  const provincialTax = subtotal * provincialTaxRate;
  const federalTax = subtotal * federalTaxRate;

  // Calculate the total
  const total = subtotal + provincialTax + federalTax;

  return (
    <Layout data={userData}>
      <div className="container mx-auto p-4">
        {/* Encabezado con enlace para regresar */}
        <div className="flex justify-between items-center mb-4">
          <h1 className="text-2xl font-bold">{t("cart.checkout")}</h1>
          <Link to="/cart" className="bg-gray-800 text-white px-4 py-2 rounded">
            ⬅ {t("cart.backToCart")}
          </Link>
        </div>

        {/* Resumen del pedido */}
        <div className="bg-white p-6 rounded-lg shadow-md">
          <h2 className="text-xl font-bold mb-4">{t("cart.purchaseSummary")}</h2>
          <div className="space-y-2">
            {cart.map((item) => (
              <div key={item.id} className="flex justify-between">
                <span>{item.name} (x{item.quantity})</span>
                <span>${(item.price * item.quantity).toFixed(2)}</span>
              </div>
            ))}
          </div>
          <div className="border-t mt-4 pt-4">
            <div className="flex justify-between">
              <span>{t("cart.subtotal")}</span>
              <span>${subtotal.toFixed(2)}</span>
            </div>
            <div className="flex justify-between">
              <span>{t("cart.provinceTax")} ({(provincialTaxValue * 100).toFixed(3)}%)</span>
              <span>${provincialTax.toFixed(2)}</span>
            </div>
            <div className="flex justify-between">
              <span>{t("cart.federalTax")} ({federalTaxValue * 100}%)</span>
              <span>${federalTax.toFixed(2)}</span>
            </div>
            <div className="flex justify-between font-bold text-lg">
              <span>{t("cart.total")}</span>
              <span>${total.toFixed(2)}</span>
            </div>
          </div>
        </div>

        {/* Formulario de pago */}
        <div className="mt-8 bg-white p-6 rounded-lg shadow-md">
          <h2 className="text-xl font-bold mb-4">{t("cart.paymentInfo")}</h2>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              alert('Redirigiendo a Moneris...'); // Simulación de redirección a Moneris
            }}
          >
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">{t("cart.cardholder")}</label>
                <input
                  type="text"
                  className="w-full p-2 border rounded"
                  placeholder="John Doe"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">{t("cart.cardNumber")}</label>
                <input
                  type="text"
                  className="w-full p-2 border rounded"
                  placeholder="1234 5678 9012 3456"
                  required
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">{t("cart.expirationDate")}</label>
                  <input
                    type="text"
                    className="w-full p-2 border rounded"
                    placeholder="MM/YY"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">{t("cart.cvv")}</label>
                  <input
                    type="text"
                    className="w-full p-2 border rounded"
                    placeholder="123"
                    required
                  />
                </div>
              </div>
              <button
                type="submit"
                className="w-full bg-green-500 text-white px-6 py-2 rounded hover:bg-green-600"
              >
                {t("cart.pay")} ${total.toFixed(2)}
              </button>
            </div>
          </form>
        </div>
      </div>
    </Layout>
  );
};

export default CheckoutPage;


export const query = graphql`
  query($language: String!) {
    locales: allLocale(filter: {language: {eq: $language}}) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;